import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import org.apache.commons.text.lookup.StringLookupFactory;

public class TemplateServlet extends HttpServlet {
    private static final Map<String, String> TEMPLATES = new HashMap<>();

    static {
        TEMPLATES.put("welcome", "Hello ${user.name}, your account ${user.id} is active since ${user.created}.");
        TEMPLATES.put("alert", "ALERT: System ${sys.hostname} reports ${alert.message} at ${alert.time}.");
        TEMPLATES.put("report", "Report for ${report.period}: Total users=${report.count}, Revenue=${report.revenue}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String templateId = req.getParameter("templateId");
        String customTemplate = req.getParameter("template");
        String dataJson = req.getParameter("data");

        if (templateId == null && customTemplate == null) {
            resp.sendError(400, "templateId or template required");
            return;
        }

        String templateStr = customTemplate != null ? customTemplate : TEMPLATES.get(templateId);
        if (templateStr == null) {
            resp.sendError(404, "Template not found");
            return;
        }

        // Parse data JSON into map for substitution
        Map<String, String> valueMap = parseSimpleJson(dataJson);

        // Apply variable interpolation using Apache Commons Text StringSubstitutor
        // This supports nested lookups and various lookup strategies
        StringSubstitutor substitutor = new StringSubstitutor(
            StringLookupFactory.INSTANCE.interpolatorStringLookup(valueMap)
        );
        substitutor.setEnableSubstitutionInVariables(true);
        substitutor.setEnableUndefinedVariableException(false);

        String result = substitutor.replace(templateStr);

        // Log the rendered template for audit
        getServletContext().log("Rendered template='" + templateId + "' with " + valueMap.size() + " vars");

        resp.setContentType("text/plain; charset=UTF-8");
        resp.getWriter().write(result);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Health check and template listing
        String action = req.getParameter("action");
        if ("list".equals(action)) {
            resp.setContentType("application/json");
            resp.getWriter().write("{\"templates\":" + TEMPLATES.keySet() + "}");
        } else {
            resp.setContentType("text/plain");
            resp.getWriter().write("OK");
        }
    }

    private Map<String, String> parseSimpleJson(String json) {
        Map<String, String> map = new HashMap<>();
        if (json == null || json.isEmpty()) return map;
        // Simple key:value parser for flat JSON
        json = json.trim();
        if (json.startsWith("{")) json = json.substring(1);
        if (json.endsWith("}")) json = json.substring(0, json.length() - 1);
        for (String pair : json.split(",")) {
            String[] kv = pair.split(":", 2);
            if (kv.length == 2) {
                String key = kv[0].trim().replaceAll("\"", "");
                String val = kv[1].trim().replaceAll("\"", "");
                map.put(key, val);
            }
        }
        return map;
    }
}
